    #[test]
    fn missing_finish_after_observed_stop_reason() {
        let evs = vec![token("hi")];
        assert_eq!(
            classify(&evs, Scenario::TruncatedAfterStopReason, false),
            Some(Violation::MissingFinish)
        );
    }

    /// Truncation with no stop reason must never be reported as a clean stop.
    #[test]
    fn finish_on_truncation_is_a_violation() {
        let evs = vec![token("hi"), finish()];
        assert_eq!(
            classify(&evs, Scenario::TruncatedMidGeneration, false),
            Some(Violation::FinishOnTruncation)
        );
    }

    /// Cancellation outranks the scenario's stop-reason expectation.
    #[test]
    fn finish_on_cancel_is_a_violation() {
        let evs = vec![token("hi"), finish()];
        assert_eq!(
            classify(&evs, Scenario::CancelAfterStopReason, true),
            Some(Violation::FinishOnCancel)
        );
    }

    /// A mid-stream error must not be followed by a clean terminal event.
    #[test]
    fn finish_after_error_is_a_violation() {
        let evs = vec![token("hi"), Err(ModelError::Unavailable), finish()];
        assert_eq!(
            classify(&evs, Scenario::ErrorAfterStopReason, false),
            Some(Violation::FinishAfterError)
        );
    }

    /// The SMA-550 shape: one call_id carrying two name-bearing deltas.
    #[test]
    fn two_named_deltas_for_one_call_id() {
        let evs = vec![
            tool("c1", Some("get_"), "{"),
            tool("c1", Some("weather"), "}"),
            Ok(ModelEvent::Finish {
                reason: FinishReason::ToolCalls,
            }),
        ];
        assert_eq!(
            classify(&evs, Scenario::ToolCallCleanStop, false),
            Some(Violation::ToolNameNotExactlyOnce {
                call_id: "c1".into(),
                count: 2
            })
        );
    }

    /// The tightening: a call that never carries a name is also a violation.
    #[test]
    fn no_named_delta_for_a_call_id() {
        let evs = vec![
            tool("c1", None, "{}"),
            Ok(ModelEvent::Finish {
                reason: FinishReason::ToolCalls,
            }),
        ];
        assert_eq!(
            classify(&evs, Scenario::ToolCallCleanStop, false),
            Some(Violation::ToolNameNotExactlyOnce {
                call_id: "c1".into(),
                count: 0
            })
        );
    }

    /// A conforming tool call passes.
    #[test]
    fn one_named_delta_conforms() {
        let evs = vec![
            tool("c1", Some("get_weather"), "{"),
            tool("c1", None, "}"),
            Ok(ModelEvent::Finish {
                reason: FinishReason::ToolCalls,
            }),
        ];
        assert_eq!(classify(&evs, Scenario::ToolCallCleanStop, false), None);
    }

    /// A cancelled stream that withholds Finish is conformant, not MissingFinish —
    /// withholding is what the contract requires of it.
    #[test]
    fn cancelled_stream_without_finish_conforms() {
        let evs = vec![token("hi")];
        assert_eq!(classify(&evs, Scenario::CancelAfterStopReason, true), None);
    }

    /// Two blank-id calls each carry their own name, as the contract requires.
    /// Confirmed to FAIL against `main` (reported count: 2).
    #[test]
    fn two_blank_id_calls_with_one_name_each_conform() {
        let evs = vec![
            tool("", Some("alpha"), "{}"),
            tool("", Some("beta"), "{}"),
            Ok(ModelEvent::Finish {
                reason: FinishReason::ToolCalls,
            }),
        ];
        assert_eq!(classify(&evs, Scenario::ToolCallCleanStop, false), None);
    }

    fn provider_data(call_id: Option<&str>) -> Result<ModelEvent, ModelError> {
        Ok(ModelEvent::ProviderData {
            provider: "test".into(),
            call_id: call_id.map(str::to_owned),
            data: serde_json::json!({ "sig": "SIG_A" }),
        })
    }

    /// Assertion 8: call-scoped data for a call that was never streamed.
    #[test]
    fn provider_data_with_unknown_call_id_is_a_violation() {
        let evs = vec![
            tool("c1", Some("get_weather"), "{}"),
            provider_data(Some("x")),
            Ok(ModelEvent::Finish {
                reason: FinishReason::ToolCalls,
            }),
        ];
        assert_eq!(
            classify(&evs, Scenario::ToolCallCleanStop, false),
            Some(Violation::ProviderDataUnknownCall {
                call_id: "x".into()
            })
        );
    }

    /// Call-scoped data that names a streamed call passes.
    #[test]
    fn provider_data_with_known_call_id_passes() {
        let evs = vec![
            tool("c1", Some("get_weather"), "{}"),
            provider_data(Some("c1")),
            Ok(ModelEvent::Finish {
                reason: FinishReason::ToolCalls,
            }),
        ];
        assert_eq!(classify(&evs, Scenario::ToolCallCleanStop, false), None);
    }

    /// A blank-id group with no name is still a translator defect.
    #[test]
    fn blank_id_with_no_name_is_a_violation() {
        let evs = vec![
            tool("", None, "{}"),
            Ok(ModelEvent::Finish {
                reason: FinishReason::ToolCalls,
            }),
        ];
        assert_eq!(
            classify(&evs, Scenario::ToolCallCleanStop, false),
            Some(Violation::ToolNameNotExactlyOnce {
                call_id: String::new(),
                count: 0
            })
        );
    }

    /// Provider data without a call id is not call-scoped.
    #[test]
    fn provider_data_without_call_id_passes() {
        let evs = vec![token("hi"), provider_data(None), finish()];
        assert_eq!(classify(&evs, Scenario::CleanStop, false), None);
    }
}
//! The pinned decline set.

use crate::Scenario;

/// Every (subject, scenario) pair that is expected to be declined, with its
/// reason. Mirrors the table in the design spec, §6.2.
///
/// The suite fails when the observed decline set differs from this in either
/// direction. Adding or removing a row is therefore a reviewed diff to a table,
/// never a one-line string literal in a match arm.
pub const DECLINED: &[(&str, Scenario, &str)] = &[
    // The tool name arrives whole in a single upstream event, so there is no
    // fragment to split.
    (
        "anthropic",
        Scenario::FragmentedToolName,
        "name arrives whole in content_block_start",
    ),
    (
        "gemini",
        Scenario::FragmentedToolName,
        "name arrives whole in functionCall",
    ),
    (
        "bedrock",
        Scenario::FragmentedToolName,
        "name arrives whole in toolUse start",
    ),
    (
        "openai/responses",
        Scenario::FragmentedToolName,
        "name arrives whole in output_item.added",
    ),
    // The window between "stop reason buffered" and "Finish emitted" lies
    // strictly between MessageStop and Metadata, with no event emitted in
    // between, so no gate edge exists.
    (
        "bedrock",
        Scenario::CancelAfterStopReason,
        "no observable event between MessageStop and Metadata",
    ),
    // terminal_events builds Usage and Finish from one upstream event, so
    // "stop reason observed but no Finish yet" is not a reachable state.
    (
        "openai/responses",
        Scenario::TruncatedAfterStopReason,
        "stop reason and Finish are the same event",
    ),
    (
        "openai/responses",
        Scenario::ErrorAfterStopReason,
        "stop reason and Finish are the same event",
    ),
    (
        "openai/responses",
        Scenario::CancelAfterStopReason,
        "stop reason and Finish are the same event",
    ),
    // The scenario serves an Anthropic thinking block, which no other
    // subject has.
    (
        "gemini",
        Scenario::ThinkingToolCallCleanStop,
        "the scenario serves an anthropic thinking block",
    ),
    (
        "bedrock",
        Scenario::ThinkingToolCallCleanStop,
        "the scenario serves an anthropic thinking block",
    ),
    (
        "litellm",
        Scenario::ThinkingToolCallCleanStop,
        "the scenario serves an anthropic thinking block",
    ),
    (
        "openai/chat",
        Scenario::ThinkingToolCallCleanStop,
        "the scenario serves an anthropic thinking block",
    ),
    (
        "openai/responses",
        Scenario::ThinkingToolCallCleanStop,
        "the scenario serves an anthropic thinking block",
    ),
];

/// The subject names registered in `tests/conformance.rs` — one `mod` per
/// subject, each holding a `StreamUnderTest` impl whose `name()` returns one
/// of these strings.
///
/// [`DECLINED`] is checked against this list because a typo'd subject name in
/// the table would otherwise be silently invisible: `assert_declines_match`
/// only ever runs with a real subject's name, filtering [`DECLINED`] down to
/// the rows for that one subject. A row naming a subject that does not exist
/// never matches that filter for *any* real subject, so it is never checked
/// in either direction — not flagged as an unexpected decline, and not
/// flagged as a pinned decline that stopped happening. The reverse direction
/// (a real subject declining something absent from the table) does fail
/// loudly; this is the direction that previously did not.
#[cfg(test)]
const REGISTERED_SUBJECTS: &[&str] = &[
    "anthropic",
    "gemini",
    "bedrock",
    "litellm",
    "openai/chat",
    "openai/responses",
];

#[cfg(test)]
mod tests {
    use super::*;

    /// Every subject named in [`DECLINED`] must be one this suite actually
    /// registers. Misspell one (e.g. `"bedrok"`) and this fails; the row
    /// would otherwise sit in the table forever, never compared against any
    /// real subject's observed declines.
    #[test]
    fn every_declined_subject_is_registered() {
        for (subject, scenario, reason) in DECLINED {
            assert!(
                REGISTERED_SUBJECTS.contains(subject),
                "DECLINED names {subject:?} for {scenario:?} ({reason:?}), which is not a \
                 registered subject name ({REGISTERED_SUBJECTS:?}) — check for a typo"
            );
        }
    }
}

